Route::prefix('storefront')->name('api.storefront.')->group(function (): void {
    Route::get('categories', [CatalogController::class, 'categories'])->name('categories.index');
    Route::get('brands', [CatalogController::class, 'brands'])->name('brands.index');
    Route::get('products', [CatalogController::class, 'products'])->name('products.index');
    Route::get('products/{product:slug}', [CatalogController::class, 'product'])->name('products.show');
    Route::get('products/{product:slug}/reviews', [StorefrontProductReviewController::class, 'index'])->name('products.reviews.index');
    Route::get('delivery-zones', [DeliveryZoneController::class, 'index'])->name('delivery-zones.index');
    Route::get('payment-methods', PaymentMethodController::class)->name('payment-methods.index');
    Route::get('homepage-sections', StorefrontHomepageSectionController::class)->name('homepage-sections.index');
    Route::get('popular-searches', StorefrontPopularSearchController::class)->name('popular-searches.index');
    Route::post('newsletter-leads', [StorefrontNewsletterLeadController::class, 'store'])->middleware('throttle:commerce-leads')->name('newsletter-leads.store');
    Route::get('cart', [CartController::class, 'show'])->name('cart.show');
    Route::post('cart/items', [CartController::class, 'addItem'])->middleware('throttle:commerce-cart')->name('cart.items.store');
    Route::patch('cart/items/{cartItem}', [CartController::class, 'updateItem'])->middleware('throttle:commerce-cart')->name('cart.items.update');
    Route::delete('cart/items/{cartItem}', [CartController::class, 'removeItem'])->middleware('throttle:commerce-cart')->name('cart.items.destroy');
    Route::delete('cart/items', [CartController::class, 'clear'])->middleware('throttle:commerce-cart')->name('cart.items.clear');
    Route::post('coupon-preview', [CouponPreviewController::class, 'store'])->middleware('throttle:commerce-public-action')->name('coupon-preview.store');
    Route::post('checkout', [CheckoutController::class, 'store'])->middleware('throttle:commerce-checkout')->name('checkout.store');
    Route::get('payments/result', [PaymentResultController::class, 'show'])->name('payments.result');
    Route::post('payments/{payment}/initiate', [PaymentInitiationController::class, 'store'])->middleware('throttle:commerce-public-action')->name('payments.initiate');
    Route::post('payments/{payment}/manual-confirmation', [ManualPaymentConfirmationController::class, 'store'])->middleware('throttle:commerce-public-action')->name('payments.manual-confirmation.store');
    Route::match(['get', 'post'], 'payments/sslcommerz/success', [SslCommerzCallbackController::class, 'success'])->name('payments.sslcommerz.success');
    Route::match(['get', 'post'], 'payments/sslcommerz/fail', [SslCommerzCallbackController::class, 'fail'])->name('payments.sslcommerz.fail');
    Route::match(['get', 'post'], 'payments/sslcommerz/cancel', [SslCommerzCallbackController::class, 'cancel'])->name('payments.sslcommerz.cancel');
    Route::match(['get', 'post'], 'payments/sslcommerz/ipn', [SslCommerzCallbackController::class, 'ipn'])->name('payments.sslcommerz.ipn');
    Route::post('orders/track', [OrderTrackingController::class, 'show'])->middleware('throttle:commerce-order-tracking')->name('orders.track');
});

Route::middleware('auth')->prefix('customer')->name('api.customer.')->group(function (): void {
    Route::get('addresses', [CustomerAddressController::class, 'index'])->name('addresses.index');
    Route::post('addresses', [CustomerAddressController::class, 'store'])->name('addresses.store');
    Route::patch('addresses/{address}', [CustomerAddressController::class, 'update'])->name('addresses.update');
    Route::delete('addresses/{address}', [CustomerAddressController::class, 'destroy'])->name('addresses.destroy');
    Route::get('orders', [CustomerOrderController::class, 'index'])->name('orders.index');
    Route::get('orders/{order}', [CustomerOrderController::class, 'show'])->name('orders.show');
    Route::get('return-requests', [CustomerReturnRequestController::class, 'index'])->name('return-requests.index');
    Route::post('return-requests', [CustomerReturnRequestController::class, 'store'])->name('return-requests.store');
    Route::get('product-reviews', [CustomerProductReviewController::class, 'index'])->name('product-reviews.index');
    Route::post('product-reviews', [CustomerProductReviewController::class, 'store'])->name('product-reviews.store');
    Route::get('support-tickets', [SupportTicketController::class, 'index'])->name('support-tickets.index');
    Route::post('support-tickets', [SupportTicketController::class, 'store'])->name('support-tickets.store');
    Route::get('wishlist', [WishlistController::class, 'index'])->name('wishlist.index');
    Route::post('wishlist', [WishlistController::class, 'store'])->name('wishlist.store');
    Route::delete('wishlist/{wishlistItem}', [WishlistController::class, 'destroy'])->name('wishlist.destroy');
});

